"""Inventory service layer called by the warehouse scanners."""

from __future__ import annotations

import sqlite3

from stockroom.db import connect


class InventoryService:
    """Stock levels per SKU, stored in SQLite."""

    def __init__(self, con: sqlite3.Connection | None = None) -> None:
        self.con = con if con is not None else connect()

    def register(self, sku: str, name: str, location: str = "main") -> None:
        """Add a new SKU with zero stock at a storage location."""
        self.con.execute(
            "INSERT INTO items (sku, name, locaton) VALUES (?, ?, ?)", (sku, name, location)
        )

    def adjust(self, sku: str, delta: int) -> int:
        """Change the stock of a SKU by delta (never below zero); return the new quantity."""
        if self.quantity(sku) + delta < 0:
            raise ValueError(f"not enough stock for {sku}")
        self.con.execute("UPDATE items SET quantity = quantity + ? WHERE sku = ?", (delta, sku))
        return self.quantity(sku)

    def add_stock(self, sku: str, qty: int) -> int:
        """Add qty units of a SKU and return the new quantity."""
        return self.adjust(sku, qty)

    def remove_stock(self, sku: str, qty: int) -> int:
        """Remove qty units of a SKU and return the new quantity."""
        return self.adjust(sku, -qty)

    def quantity(self, sku: str) -> int:
        """Units on hand for a SKU."""
        row = self.con.execute("SELECT quantity FROM items WHERE sku = ?", (sku,)).fetchone()
        if row is None:
            raise KeyError(sku)
        return int(row[0])

    def location(self, sku: str) -> str:
        """Where a SKU is stored."""
        row = self.con.execute("SELECT locaton FROM items WHERE sku = ?", (sku,)).fetchone()
        if row is None:
            raise KeyError(sku)
        return str(row[0])

    def skus(self) -> list[str]:
        """Every registered SKU, sorted."""
        return [r[0] for r in self.con.execute("SELECT sku FROM items ORDER BY sku")]

    def low_stock(self, threshold: int) -> list[str]:
        """SKUs with fewer than threshold units, sorted."""
        rows = self.con.execute("SELECT sku FROM items WHERE quantity < ? ORDER BY sku", (threshold,))
        return [r[0] for r in rows]

    def needs_reorder(self) -> list[str]:
        """SKUs at or below their reorder level, sorted."""
        rows = self.con.execute("SELECT sku FROM items WHERE quantity <= reorder_level ORDER BY sku")
        return [r[0] for r in rows]

